1	//! Wire-format integration tests for the Responses API backend.
2	//!
3	//! These tests stand up a wiremock server, point an `OpenAiModel` at
4	//! `base_url(server.uri())`, and assert on the SSE bytes the provider sees.
5	//!
6	//! The Responses API SSE event JSON must include all required fields
7	//! (no optional-only shapes). See `ResponseStreamEvent` in async-openai 0.40
8	//! for the exact schema.
9	
10	use futures_util::StreamExt;
11	use paigasus_helikon_core::{
12	    CancellationToken, ContentPart, FinishReason, Item, Model, ModelEvent, ModelRequest,
13	};
14	use paigasus_helikon_providers_openai::OpenAiModel;
15	use wiremock::matchers::{body_string_contains, method, path};
16	use wiremock::{Mock, MockServer, ResponseTemplate};
17	
18	fn user(text: &str) -> Item {
19	    Item::UserMessage {
20	        content: vec![ContentPart::Text {
21	            text: text.to_owned(),
22	        }],
23	    }
24	}
25	
26	/// Minimal JSON for a `response.output_text.delta` event (all required fields).
27	fn text_delta_event(seq: u64, delta: &str) -> String {
28	    format!(
29	        r#"{{"type":"response.output_text.delta","sequence_number":{seq},"item_id":"msg_01","output_index":0,"content_index":0,"delta":"{delta}"}}"#
30	    )
31	}
32	
33	/// Minimal JSON for a `response.completed` event (all required fields).
34	///
35	/// `ResponseCompletedEvent` → `response: Response`.
36	/// `Response` requires: `created_at`, `id`, `model`, `object`, `output[]`, `status`.
37	/// `ResponseUsage` requires: `input_tokens`, `input_tokens_details.cached_tokens`,
38	/// `output_tokens`, `output_tokens_details.reasoning_tokens`, `total_tokens`.
39	fn completed_event(seq: u64, input_tokens: u32, output_tokens: u32) -> String {
40	    let total = input_tokens + output_tokens;
41	    format!(
42	        r#"{{"type":"response.completed","sequence_number":{seq},"response":{{"id":"resp_01","object":"response","created_at":1,"model":"gpt-5","output":[],"status":"completed","usage":{{"input_tokens":{input_tokens},"input_tokens_details":{{"cached_tokens":0}},"output_tokens":{output_tokens},"output_tokens_details":{{"reasoning_tokens":0}},"total_tokens":{total}}}}}}}"#
43	    )
44	}
45	
46	/// SSE wire representation of a single data event followed by `[DONE]`.
47	fn sse(events: &[String]) -> String {
48	    let mut out = String::new();
49	    for event in events {
50	        out.push_str("data: ");
51	        out.push_str(event);
52	        out.push_str("\n\n");
53	    }
54	    out.push_str("data: [DONE]\n\n");
55	    out
56	}
57	
58	#[tokio::test]
59	async fn happy_path_text_completion() {
60	    let server = MockServer::start().await;
61	
62	    let body = sse(&[text_delta_event(1, "hi"), completed_event(2, 5, 1)]);
63	
64	    Mock::given(method("POST"))
65	        .and(path("/responses"))
66	        .respond_with(ResponseTemplate::new(200).set_body_raw(body.as_bytes(), "text/event-stream"))
67	        .mount(&server)
68	        .await;
69	
70	    let model = OpenAiModel::responses("gpt-5")
71	        .api_key("sk-test")
72	        .base_url(server.uri())
73	        .build()
74	        .unwrap();
75	
76	    let mut req = ModelRequest::new();
77	    req.messages = vec![user("hi")];
78	
79	    let stream = model.invoke(req, CancellationToken::new()).await.unwrap();
80	
81	    let events: Vec<ModelEvent> = stream
82	        .collect::<Vec<_>>()
83	        .await
84	        .into_iter()
85	        .map(|r| r.expect("event was Err"))
86	        .collect();
87	
88	    // First event must be the text token delta.
89	    assert!(
90	        matches!(events[0], ModelEvent::TokenDelta { ref text } if text == "hi"),
91	        "expected TokenDelta(\"hi\") at events[0], got {:?}",
92	        events[0]
93	    );
94	
95	    // A Usage event must be present.
96	    assert!(
97	        events.iter().any(|e| matches!(
98	            e,
99	            ModelEvent::Usage {
100	                input_tokens: 5,
101	                output_tokens: 1,
102	                ..
103	            }
104	        )),
105	        "expected a Usage {{ input_tokens: 5, output_tokens: 1 }} event, events = {events:?}"
106	    );
107	
108	    // Finish(Stop) must be the last event (status=completed → Stop).
109	    assert!(
110	        matches!(
111	            events.last().unwrap(),
112	            ModelEvent::Finish {
113	                reason: FinishReason::Stop
114	            }
115	        ),
116	        "expected Finish(Stop) as last event, got {:?}",
117	        events.last()
118	    );
119	}
120	
121	#[tokio::test]
122	async fn previous_response_id_passes_through_to_request_body() {
123	    let server = MockServer::start().await;
124	
125	    let body = sse(&[completed_event(1, 1, 1)]);
126	
127	    Mock::given(method("POST"))
128	        .and(path("/responses"))
129	        .and(body_string_contains(r#""previous_response_id":"resp_abc""#))
130	        .respond_with(ResponseTemplate::new(200).set_body_raw(body.as_bytes(), "text/event-stream"))
131	        .expect(1)
132	        .mount(&server)
133	        .await;
134	
135	    let model = OpenAiModel::responses("gpt-5")
136	        .api_key("sk-test")
137	        .base_url(server.uri())
138	        .build()
139	        .unwrap();
140	
141	    let mut req = ModelRequest::new();
142	    req.messages = vec![user("continue")];
143	    req.model_settings.previous_response_id = Some("resp_abc".to_owned());
144	
145	    let stream = model.invoke(req, CancellationToken::new()).await.unwrap();
146	
147	    // Drain the stream to ensure the request is sent and wiremock's `.expect(1)`
148	    // assertion fires on drop.
149	    let _: Vec<_> = stream.collect().await;
150	}
