1	//! Responses API backend.
2	//!
3	//! Always streams (async-openai's `create_stream` sets `stream: true`
4	//! automatically). The SSE stream is translated by [`ResponsesTranslator`]
5	//! into `ModelEvent`s.
6	
7	use std::collections::hash_map::Entry;
8	use std::collections::{HashMap, HashSet};
9	
10	use async_openai::traits::EventType as _;
11	use async_openai::types::responses::{
12	    CreateResponse, FunctionTool, InputItem, InputParam, OutputItem, OutputStatus,
13	    ResponseFormatJsonSchema, ResponseStreamEvent, ResponseTextParam, ResponseUsage, Status,
