94	/// Build the typed request for the Responses API.
95	fn build_request(
96	    model: &OpenAiModel,
97	    request: &ModelRequest,
98	) -> Result<CreateResponse, ModelError> {
99	    // Translate Item messages → Responses API InputParam via JSON round-trip.
100	    let input_value = to_responses_input(&request.messages);
101	    let input_items: Vec<InputItem> = serde_json::from_value(input_value)
102	        .map_err(|e: serde_json::Error| ModelError::Other(anyhow::anyhow!(e)))?;
103	
104	    let mut body = CreateResponse {
105	        model: Some(model.model_id.clone()),
106	        input: InputParam::Items(input_items),
107	        ..Default::default()
108	    };
109	
110	    // Tools.
111	    if !request.tools.is_empty() {
112	        let tools: Vec<Tool> = request
113	            .tools
114	            .iter()
115	            .map(|td| {
116	                Tool::Function(FunctionTool {
117	                    name: td.name.clone(),
118	                    description: Some(td.description.clone()),
119	                    parameters: Some(to_strict_schema(&td.schema)),
120	                    strict: Some(true),
121	                    defer_loading: None,
122	                    // Opt-in capabilities added by async-openai 0.42 that this
123	                    // SDK does not expose. All three are
124	                    // `skip_serializing_if = "Option::is_none"`, so `None`
125	                    // keeps the wire payload identical to the one we sent
126	                    // before the bump and lets the server apply its defaults.
127	                    //
128	                    // `async`: server-side deferred tool execution. Our tool
129	                    // loop is synchronous — the runner executes the tool and
130	                    // returns the output in the next request — so we never
131	                    // want the model to treat a tool as asynchronous.
132	                    r#async: None,
133	                    // `output_schema`: declares a JSON schema for the tool's
134	                    // return value. `ToolDef` carries only an input schema, so
135	                    // we have nothing to declare.
136	                    output_schema: None,
137	                    // `allowed_callers`: restricts a tool to `direct` and/or
138	                    // `programmatic` callers. `None` means no restriction.
139	                    allowed_callers: None,
140	                })
141	            })
142	            .collect();
143	        body.tools = Some(tools);
144	    }
145	
146	    // ModelSettings passthrough.
147	    if let Some(t) = request.model_settings.temperature {
148	        body.temperature = Some(t);
149	    }
150	    if let Some(p) = request.model_settings.top_p {
151	        body.top_p = Some(p);
152	    }
153	    if let Some(m) = request.model_settings.max_output_tokens {
154	        body.max_output_tokens = Some(m);
155	    }
156	
157	    // Tool choice.
158	    if let Some(tc) = &request.model_settings.tool_choice {
159	        body.tool_choice = Some(translate_tool_choice(tc));
160	    }
161	
162	    // Response format → Responses API `text.format` field.
163	    // Build typed TextResponseFormatConfiguration directly (the shapes differ
164	    // between Chat Completions and Responses API, so we cannot reuse
165	    // `to_openai_response_format` here).
166	    if let Some(rf) = &request.model_settings.response_format {
167	        let format = match rf {
168	            ResponseFormat::Text => None,
169	            ResponseFormat::JsonObject => Some(TextResponseFormatConfiguration::JsonObject),
170	            ResponseFormat::JsonSchema {
171	                name,
172	                schema,
173	                strict,
174	            } => {
175	                let s = if *strict {
176	                    to_strict_schema(schema)
177	                } else {
178	                    schema.clone()
179	                };
180	                Some(TextResponseFormatConfiguration::JsonSchema(
181	                    ResponseFormatJsonSchema {
182	                        name: name.clone(),
183	                        schema: s,
184	                        strict: Some(*strict),
185	                        description: None,
186	                    },
187	                ))
188	            }
189	            // Future variants from #[non_exhaustive]; default to no constraint.
190	            _ => None,
191	        };
192	        if let Some(fmt) = format {
193	            let mut text_param = body.text.take().unwrap_or(ResponseTextParam {
194	                format: TextResponseFormatConfiguration::Text,
195	                verbosity: None,
196	            });
197	            text_param.format = fmt;
198	            body.text = Some(text_param);
199	        }
200	    }
201	
202	    // previous_response_id — thread through unmodified.
203	    if let Some(id) = &request.model_settings.previous_response_id {
204	        body.previous_response_id = Some(id.clone());
205	    }
206	
207	    Ok(body)
208	}
