28	/// Entry point for the Responses API backend. Always streams.
29	///
30	/// Builds a streaming Responses request via async-openai, translates
31	/// the SSE stream through [`ResponsesTranslator`] into a
32	/// `BoxStream<Result<ModelEvent, ModelError>>`.
33	///
34	/// Cancellation via [`CancellationToken`] is honoured at both the initial
35	/// request future and each poll of the upstream SSE stream (`tokio::select!`
36	/// biased toward the cancel arm).
37	pub(crate) async fn invoke(
38	    model: &OpenAiModel,
39	    request: ModelRequest,
40	    cancel: CancellationToken,
41	) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
42	    let body = build_request(model, &request)?;
43	    let client = model.client.clone();
44	
45	    let s = stream! {
46	        let responses_client = client.responses();
47	        let create_fut = responses_client.create_stream(body);
48	
49	        let response = tokio::select! {
50	            biased;
51	            _ = cancel.cancelled() => return,
52	            r = create_fut => r,
53	        };
54	
55	        let mut upstream = match response {
56	            Ok(s) => s,
57	            Err(e) => {
58	                yield Err(map_openai_error(e));
59	                return;
60	            }
61	        };
62	
63	        let mut translator = ResponsesTranslator::new();
64	        loop {
65	            let next = tokio::select! {
66	                biased;
67	                _ = cancel.cancelled() => return,
68	                n = upstream.next() => n,
69	            };
70	            match next {
71	                None => return,
72	                Some(Err(e)) => {
73	                    yield Err(map_openai_error(e));
74	                    return;
75	                }
76	                Some(Ok(event)) => match translator.consume(event) {
77	                    Ok(events) => {
78	                        for ev in events {
79	                            yield Ok(ev);
80	                        }
81	                    }
82	                    Err(e) => {
83	                        yield Err(e);
84	                        return;
85	                    }
86	                }
87	            }
88	        }
89	    };
90	
91	    Ok(Box::pin(s))
92	}
