210	/// Translate a [`ToolChoice`] into async-openai's Responses API
211	/// [`ToolChoiceParam`].
212	fn translate_tool_choice(tc: &ToolChoice) -> ToolChoiceParam {
213	    match tc {
214	        ToolChoice::Auto => ToolChoiceParam::Option(ToolChoiceOptions::Auto),
215	        ToolChoice::Required => ToolChoiceParam::Option(ToolChoiceOptions::Required),
216	        ToolChoice::None => ToolChoiceParam::Option(ToolChoiceOptions::None),
217	        ToolChoice::Tool { name } => {
218	            use async_openai::types::responses::ToolChoiceFunction;
219	            ToolChoiceParam::Function(ToolChoiceFunction { name: name.clone() })
220	        }
221	        // ToolChoice is #[non_exhaustive]; new variants default to Auto.
222	        _ => ToolChoiceParam::Option(ToolChoiceOptions::Auto),
223	    }
224	}
