1	//! A paced HTTP/1.1 server that plays a scripted streaming response back at a
2	//! real client.
3	//!
4	//! `wiremock` writes a whole body in one `set_body_raw` call, so it cannot
5	//! express the three endings this suite has to tell apart: a body that pauses
6	//! mid-flight, a body that ends cleanly, and a body that is torn down without
7	//! its terminating chunk. This module can, which is what lets the conformance
8	//! scenarios distinguish "the stream was truncated" from "the stream errored".
9	//!
10	//! Everything here talks real HTTP over a loopback socket, so the provider
11	//! drivers under test run their production transport unmodified.
12	
13	use std::convert::Infallible;
14	use std::io;
15	use std::sync::{Arc, Mutex as StdMutex};
16	use std::task::Poll;
17	
18	use futures_util::stream::{self, BoxStream, Stream, StreamExt};
19	use http_body_util::{BodyExt, StreamBody};
20	use hyper::body::{Bytes, Frame, Incoming};
21	use hyper::http::HeaderMap;
22	use hyper::server::conn::http1;
23	use hyper::service::service_fn;
24	use hyper::{Request, Response};
25	use hyper_util::rt::TokioIo;
26	use tokio::net::TcpListener;
27	use tokio::sync::{mpsc, oneshot, Mutex};
28	
29	use crate::GateHandle;
30	
31	/// One frame of the scripted body: either bytes, or the failure that ends the
32	/// response uncleanly.
33	type ScriptFrame = Result<Frame<Bytes>, io::Error>;
34	
35	/// The response body type. Boxing the stream keeps this nameable, which the
36	/// `service_fn` return type needs.
37	type ScriptBody = StreamBody<BoxStream<'static, ScriptFrame>>;
38	
39	/// How a scripted response body terminates once every chunk has been written.
40	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
41	pub enum Ending {
42	    /// End the body normally. hyper writes the terminating chunk, so the client
43	    /// observes an ordinary end-of-stream.
44	    Clean,
45	    /// End the body uncleanly. The body stream yields an error, so hyper tears
46	    /// the connection down *without* the terminating chunk and the client
47	    /// observes a transport error rather than an end-of-stream. This is the
48	    /// distinction the error scenarios rest on.
49	    Abort,
50	}
51	
52	/// One scripted streaming response.
53	#[derive(Debug, Clone)]
54	pub struct Script {
55	    /// Value for the response's `content-type` header, e.g.
56	    /// `"text/event-stream"`.
57	    pub content_type: &'static str,
58	    /// Body chunks, handed to the response body in order. Each is written as
59	    /// its own HTTP chunk, so a fixture can split a wire event wherever the
60	    /// scenario needs it split.
61	    pub chunks: Vec<Vec<u8>>,
62	    /// Pause once this many chunks have been handed over, and resume only when
63	    /// the gate is released. `Some(0)` pauses before the first chunk;
64	    /// `Some(chunks.len())` pauses after the last one but before the ending, so
65	    /// the body is still open. `None` sends everything without pausing. A value
66	    /// above `chunks.len()` never pauses, which makes the gate a no-op — keep it
67	    /// within `0..=chunks.len()`.
68	    pub gate_after: Option<usize>,
69	    /// How the body terminates once every chunk has been written.
70	    pub ending: Ending,
71	}
72	
73	/// A running paced server, bound to an ephemeral loopback port.
74	///
75	/// The accept loop is spawned detached and is *not* stopped when this value is
76	/// dropped: a caller may hand a still-streaming response back to its own caller
77	/// and drop the server, and the response must keep flowing. The listener is
78	/// released when the test process exits.
79	pub struct PacedServer {
80	    /// The ephemeral port the listener bound to.
81	    port: u16,
82	    /// Present exactly when the script set `gate_after`.
83	    gate: Option<GateHandle>,
84	    /// Filled in by the first request to arrive. See
85	    /// [`PacedServer::first_request_headers`].
86	    first_request_headers: CapturedHeaders,
87	}
88	
89	/// The first request's header map, shared between the handler that fills it and
90	/// the [`PacedServer`] that hands it back.
91	///
92	/// `std::sync::Mutex` rather than the `tokio` one: the critical section is a
93	/// clone with no `await` in it, so an async mutex would buy nothing.
94	type CapturedHeaders = Arc<StdMutex<Option<HeaderMap>>>;
95	
96	/// What the request handler needs, shared across the connections of one server.
97	struct Shared {
98	    /// The script being played.
99	    script: Script,
100	    /// Taken by the first request; a `oneshot` can only be awaited once, and
101	    /// one server plays its script to one request.
102	    gate_rx: Mutex<Option<oneshot::Receiver<()>>>,
103	    /// Write side of [`PacedServer::first_request_headers`].
104	    first_request_headers: CapturedHeaders,
105	}
106	
107	impl PacedServer {
108	    /// Bind an ephemeral loopback port and start serving `script`.
109	    ///
110	    /// Every request gets the same script, but the gate — if the script has one
111	    /// — fires for the first request only.
112	    pub async fn start(script: Script) -> Self {
113	        let listener = TcpListener::bind(("127.0.0.1", 0))
114	            .await
115	            .expect("paced server should bind an ephemeral loopback port");
116	        let port = listener
117	            .local_addr()
118	            .expect("bound listener should have a local address")
119	            .port();
120	
121	        let (gate, gate_rx) = if script.gate_after.is_some() {
122	            let (tx, rx) = oneshot::channel();
123	            (Some(GateHandle { tx }), Some(rx))
124	        } else {
125	            (None, None)
126	        };
127	
128	        let first_request_headers: CapturedHeaders = Arc::new(StdMutex::new(None));
129	
130	        let shared = Arc::new(Shared {
131	            script,
132	            gate_rx: Mutex::new(gate_rx),
133	            first_request_headers: Arc::clone(&first_request_headers),
134	        });
135	
136	        tokio::spawn(async move {
137	            loop {
138	                let (stream, _peer) = match listener.accept().await {
139	                    Ok(accepted) => accepted,
140	                    // A peer that vanished between the SYN and the accept kills
141	                    // only that connection. Bailing out here would drop the
142	                    // listener, and every later connect would get
143	                    // ECONNREFUSED — which reads as a provider bug in the
144	                    // subject tasks rather than as a dead test server.
145	                    Err(err) if is_transient_accept_error(&err) => continue,
146	                    Err(_) => break,
147	                };
148	                let shared = Arc::clone(&shared);
149	                tokio::spawn(async move {
150	                    let service =
151	                        service_fn(move |req: Request<Incoming>| respond(Arc::clone(&shared), req));
152	                    // No `graceful_shutdown`: the abort ending has to be an
153	                    // unclean termination, and a graceful shutdown would flush
154	                    // a well-formed end of body first.
155	                    let _ = http1::Builder::new()
156	                        .serve_connection(TokioIo::new(stream), service)
157	                        .await;
158	                });
159	            }
160	        });
161	
162	        Self {
163	            port,
164	            gate,
165	            first_request_headers,
166	        }
167	    }
168	
169	    /// The origin to point a client at, e.g. `http://127.0.0.1:52413`.
170	    pub fn base_url(&self) -> String {
171	        format!("http://127.0.0.1:{}", self.port)
172	    }
173	
174	    /// Take the gate, if the script declared one. Releasing the returned handle
175	    /// lets the server send the chunks it is holding back. Returns `None` on
176	    /// the second call, and for a script with no `gate_after`.
177	    pub fn take_gate(&mut self) -> Option<GateHandle> {
178	        self.gate.take()
179	    }
180	
181	    /// The headers of the **first** request this server received, or `None` if
182	    /// no request has arrived yet.
183	    ///
184	    /// This exists so a subject can assert what its provider's driver actually
185	    /// put on the wire, not merely that a round-trip happened. The Bedrock
186	    /// subject uses it to prove the AWS SDK really signed the request: the
187	    /// server ignores `Authorization` when responding, so without reading it
188	    /// back, an unsigned request would pass a transport test exactly as well as
189	    /// a signed one.
190	    ///
191	    /// Deliberately narrow — first request only, headers only, no method, path
192	    /// or body. This is not a general-purpose request recorder, and it should
193	    /// not grow into one; a subject that needs to assert on a request *body*
194	    /// wants a different tool. First-only also means a retried request cannot
195	    /// overwrite the record of the original.
196	    pub fn first_request_headers(&self) -> Option<HeaderMap> {
197	        self.first_request_headers
198	            .lock()
199	            .expect("captured-headers mutex should not be poisoned")
200	            .clone()
201	    }
202	}
203	
204	/// Handle one request: drain its body, then stream the script back.
205	async fn respond(
206	    shared: Arc<Shared>,
207	    req: Request<Incoming>,
208	) -> Result<Response<ScriptBody>, Infallible> {
209	    // Record the first request's headers before the request is consumed. Only
210	    // the first: a retry must not overwrite what the original attempt sent.
211	    {
212	        let mut slot = shared
213	            .first_request_headers
214	            .lock()
215	            .expect("captured-headers mutex should not be poisoned");
216	        if slot.is_none() {
217	            *slot = Some(req.headers().clone());
218	        }
219	    }
220	
221	    // Drain the request body before responding. A client that is still writing
222	    // when the connection goes away can see a reset instead of the response, and
223	    // that would present as a provider bug.
224	    let _ = req.into_body().collect().await;
225	
226	    let gate_rx = shared.gate_rx.lock().await.take();
227	
228	    // Unbounded on purpose. A bounded channel would add back-pressure that
229	    // usually — but only usually — keeps the abort error from reaching hyper in
230	    // the same poll pass as the last chunk, which silently masks a missing
231	    // deferral in `script_frames` and makes that bug unreproducible in a test.
232	    // With no back-pressure, the deferral is the single mechanism responsible
233	    // for the abort flush, and its removal fails a test every time.
234	    let (tx, rx) = mpsc::unbounded_channel::<ScriptFrame>();
235	    let feeder = Arc::clone(&shared);
236	    tokio::spawn(async move { feed(feeder, gate_rx, tx).await });
237	
238	    let body = StreamBody::new(script_frames(rx).boxed());
239	
240	    Ok(Response::builder()
241	        .status(200)
242	        .header("content-type", shared.script.content_type)
243	        .body(body)
244	        .expect("scripted response should build"))
245	}
246	
247	/// Turn the feeder's channel into the stream hyper writes from, deferring the
248	/// abort error by exactly one poll.
249	///
250	/// That deferral is load-bearing. hyper's connection loop runs `poll_write`
251	/// then `poll_flush`, and an error out of the body escapes `poll_write` before
252	/// `poll_flush` is reached in the same pass. So if the error were handed over in
253	/// the same pass that produced the last chunk, hyper would tear the connection
254	/// down with the response head and every chunk still sitting in its write
255	/// buffer, and the client would see a connection that closed before it ever got
256	/// a response — not the truncated body the abort scenarios need. Returning
257	/// `Pending` once (with an immediate self-wake) forces the intervening flush, so
258	/// the client receives the head and every chunk, and only then loses the
259	/// connection mid-body.
260	///
261	/// The guarantee has a limit worth knowing before you lean on it: this forces
262	/// hyper to *call* `poll_flush`, not to have drained the socket. A scripted body
263	/// larger than the socket send buffer (~64 KB on loopback) can still lose its
264	/// tail when the abort lands, because the flush would return `Pending` with
265	/// bytes still buffered. Every conformance fixture is orders of magnitude
266	/// smaller than that; if you add a large abort fixture, re-check this.
267	fn script_frames(
268	    mut rx: mpsc::UnboundedReceiver<ScriptFrame>,
269	) -> impl Stream<Item = ScriptFrame> + Send {
270	    let mut deferred: Option<io::Error> = None;
271	    stream::poll_fn(move |cx| {
272	        if let Some(err) = deferred.take() {
273	            return Poll::Ready(Some(Err(err)));
274	        }
275	        match rx.poll_recv(cx) {
276	            Poll::Ready(Some(Err(err))) => {
277	                // Defer by one poll so hyper flushes what it has already
278	                // written before this error tears the connection down. Removing
279	                // this makes the client receive an empty body on every abort;
280	                // `abort_delivers_buffered_chunks_before_erroring` is the test
281	                // that catches it.
282	                deferred = Some(err);
283	                cx.waker().wake_by_ref();
284	                Poll::Pending
285	            }
286	            other => other,
287	        }
288	    })
289	}
290	
291	/// Push the script's chunks into `tx`, pausing at the gate, then apply the
292	/// ending.
293	async fn feed(
294	    shared: Arc<Shared>,
295	    mut gate_rx: Option<oneshot::Receiver<()>>,
296	    tx: mpsc::UnboundedSender<ScriptFrame>,
297	) {
298	    let script = &shared.script;
299	
300	    for (already_sent, chunk) in script.chunks.iter().enumerate() {
301	        if script.gate_after == Some(already_sent) {
302	            wait_for_gate(&mut gate_rx).await;
303	        }
304	        if tx
305	            .send(Ok(Frame::data(Bytes::from(chunk.clone()))))
306	            .is_err()
307	        {
308	            // The client hung up, or the connection died. Nothing left to play.
309	            return;
310	        }
311	    }
312	
313	    if script.gate_after == Some(script.chunks.len()) {
314	        wait_for_gate(&mut gate_rx).await;
315	    }
316	
317	    match script.ending {
318	        // Dropping the sender ends the stream, and hyper writes the terminating
319	        // chunk.
320	        Ending::Clean => drop(tx),
321	        // An error out of the body makes hyper abandon the connection without
322	        // the terminating chunk, so the client sees a transport error.
323	        Ending::Abort => {
324	            let _ = tx.send(Err(io::Error::other("aborted")));
325	        }
326	    }
327	}
328	
329	/// Whether an `accept` error killed only one connection rather than the
330	/// listener.
331	fn is_transient_accept_error(err: &io::Error) -> bool {
332	    matches!(
333	        err.kind(),
334	        io::ErrorKind::ConnectionAborted
335	            | io::ErrorKind::ConnectionReset
336	            | io::ErrorKind::ConnectionRefused
337	            | io::ErrorKind::Interrupted
338	    )
