280	///    `classify` function.
281	///
282	/// Afterwards the observed declines are compared against the pinned
283	/// [`DECLINED`] table in both directions.
284	pub async fn assert_conforms(subject: &impl StreamUnderTest) {
285	    let name = subject.name();
286	    let mut declined: Vec<(Scenario, &'static str)> = Vec::new();
287	
288	    for &scenario in Scenario::ALL {
289	        let cancel = CancellationToken::new();
290	        let (stream, gate) = match subject.stream(scenario, cancel.clone()).await {
291	            Outcome::Declined(reason) => {
292	                declined.push((scenario, reason));
293	                continue;
294	            }
295	            Outcome::Served { stream, gate } => (stream, gate),
296	        };
297	
298	        let declared = subject.encodes_stop_reason(scenario);
299	        let expected = scenario.expects_stop_reason();
300	        if declared != expected {
301	            fail(
302	                name,
303	                scenario,
304	                &Violation::StopReasonDeclarationMismatch { expected, declared },
305	                "the subject's fixture does not encode what this scenario requires, so \
306	                 assertions 3 and 4 would be checked against the wrong condition",
307	            );
308	        }
309	
310	        let cancelled = is_cancel_scenario(scenario);
311	        if cancelled && gate.is_none() {
312	            fail(
313	                name,
314	                scenario,
315	                &Violation::InsufficientEvidence(
316	                    "a cancellation scenario was served without a gate, so the whole body was \
317	                     already on its way and cancellation could not truncate anything",
318	                ),
319	                "give the script a `gate_after` and hand the `GateHandle` back in \
320	                 `Outcome::Served`",
321	            );
322	        }
323	
324	        let Ok(drained) =
325	            tokio::time::timeout(DRAIN_TIMEOUT, drain(stream, gate, scenario, cancel)).await
326	        else {
327	            fail(
328	                name,
329	                scenario,
330	                &Violation::Timeout,
331	                "the stream never ended. For a cancellation scenario, check that the driver \
332	                 selects on the cancellation token while awaiting the next chunk; otherwise \
333	                 check that the script's ending actually closes the body",
334	            );
335	        };
336	
337	        if let Some(violation) = floor_violation(
338	            scenario,
339	            &drained.events,
340	            subject.fixture_tool_name(),
341	            subject.fixture_finish_reason(scenario),
342	        ) {
343	            fail(
344	                name,
345	                scenario,
346	                &violation,
347	                &format!("observed: {}", summarise(&drained.events)),
348	            );
349	        }
350	
351	        if let Some(violation) = drained.cancel_violation() {
352	            fail(
353	                name,
354	                scenario,
355	                &violation,
356	                &format!("observed: {}", summarise(&drained.events)),
357	            );
358	        }
359	
360	        if let Some(violation) = classify(&drained.events, scenario, cancelled) {
361	            fail(
362	                name,
363	                scenario,
364	                &violation,
365	                &format!("observed: {}", summarise(&drained.events)),
366	            );
367	        }
368	    }
369	
370	    assert_declines_match(name, &declined);
371	}
372	
373	/// Whether `scenario` cancels the stream part-way through.
374	fn is_cancel_scenario(scenario: Scenario) -> bool {
375	    matches!(
376	        scenario,
377	        Scenario::CancelMidGeneration | Scenario::CancelAfterStopReason
378	    )
379	}
380	
